<?php
namespace Tests\Feature; use App\Models\{SchoolClass,Student,User}; use App\Services\StudentBarcodeService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AttendanceSecurityTest extends TestCase{use RefreshDatabase;private function setupData():array{$a=SchoolClass::create(['class_name'=>'1A','grade_level'=>1,'academic_year'=>'2026/2027']);$b=SchoolClass::create(['class_name'=>'1B','grade_level'=>1,'academic_year'=>'2026/2027']);$admin=User::factory()->create();$wali=User::factory()->create(['role'=>'wali_kelas','class_id'=>$a->id]);$student=Student::create(['nis'=>'001','name'=>'Siswa B','gender'=>'L','class_id'=>$b->id,'barcode_token'=>app(StudentBarcodeService::class)->generateToken()]);return compact('a','b','admin','wali','student');}public function test_admin_login_works():void{$u=User::factory()->create(['email'=>'admin@test.local','password'=>'password']);$this->post('/login',['login'=>$u->email,'password'=>'password'])->assertRedirect('/dashboard');}public function test_wali_cannot_open_other_class_student():void{$d=$this->setupData();$this->actingAs($d['wali'])->get(route('students.show',$d['student']))->assertForbidden();}public function test_barcode_is_unique_and_can_be_regenerated():void{$d=$this->setupData();$old=$d['student']->barcode_token;app(StudentBarcodeService::class)->regenerate($d['student']);$this->assertNotEquals($old,$d['student']->fresh()->barcode_token);$this->actingAs($d['admin'])->postJson(route('attendance.scan.store'),['token'=>$old])->assertUnprocessable();}public function test_scan_cannot_duplicate():void{$d=$this->setupData();$this->actingAs($d['admin'])->postJson(route('attendance.scan.store'),['token'=>$d['student']->barcode_token])->assertOk();$this->postJson(route('attendance.scan.store'),['token'=>$d['student']->barcode_token])->assertUnprocessable();$this->assertDatabaseCount('attendances',1);}public function test_wali_cannot_scan_other_class():void{$d=$this->setupData();$this->actingAs($d['wali'])->postJson(route('attendance.scan.store'),['token'=>$d['student']->barcode_token])->assertUnprocessable();}}
